namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Drop table if exists (ignore result as table may not exist)
  sqlgen::drop_table<Product>(conn);

  // Create the Product table
  auto create_result = sqlgen::create_table<Product>(conn);
  if (!create_result) {
    return false;
  }

  // Begin transaction
  auto txn = sqlgen::begin_transaction(conn);
  if (!txn) {
    return false;
  }

  // Insert all products in batch within the transaction
  for (const auto& product : products) {
    auto insert_result = sqlgen::insert(txn, product);
    if (!insert_result) {
      // If any insert fails, return false (transaction will rollback)
      return false;
    }
  }

  // Commit the transaction
  auto commit_result = sqlgen::commit(txn);
  return static_cast<bool>(commit_result);
}

}  // namespace batch_insert_products
