  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // 2. Begin transaction and execute delete operation
  auto result = sqlgen::begin_transaction(conn)
    .and_then([](auto txn) {
      // 3. Define the cutoff date (2025-01-01)
      auto cutoff_date = sqlgen::DateTime("2025-01-01");

      // 4. Delete users who have not logged in since 2025-01-01
      return txn->execute(
        sqlgen::delete_from<User>()
          .where(sqlgen::col<"last_login"> < cutoff_date)
      ).and_then([txn](auto _) {
        // 5. Commit the transaction
        return txn->commit();
      });
    });

  // 6. Return operation result of commit
  return result.value_or(0);
}

