struct Order {
  sqlgen::PrimaryKey<int> order_id;
  sqlgen::ForeignKey<int, Customer, "customer_id"> customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  // 1. Connect to SQLite database
  auto conn_result = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = *conn_result;

  // 2. Create tables
  conn->execute(conn->to_sql(sqlgen::transpilation::to_create_table<Customer>()));
  conn->execute(conn->to_sql(sqlgen::transpilation::to_create_table<Product>()));
  conn->execute(conn->to_sql(sqlgen::transpilation::to_create_table<Order>()));
  conn->execute(conn->to_sql(sqlgen::transpilation::to_create_table<OrderItem>()));

  // 3. Define intermediate result struct with matching field names
  struct QueryResult {
    std::string name;  // Product name
    sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;  // Order date
    int quantity;  // Order quantity
  };

  // 4. Query the database with joins
  auto query = sqlgen::select_from<Customer, "c">(
    sqlgen::col<"p", &Product::name>,
    sqlgen::col<"o", &Order::order_date>,
    sqlgen::col<"oi", &OrderItem::quantity>
  )
  | sqlgen::join<Order, "o">(sqlgen::col<"c", &Customer::customer_id> == sqlgen::col<"o", &Order::customer_id>)
  | sqlgen::join<OrderItem, "oi">(sqlgen::col<"o", &Order::order_id> == sqlgen::col<"oi", &OrderItem::order_id>)
  | sqlgen::join<Product, "p">(sqlgen::col<"oi", &OrderItem::product_id> == sqlgen::col<"p", &Product::product_id>)
  | sqlgen::where(sqlgen::col<"c", &Customer::customer_id> == customer_id)
  | sqlgen::order_by(sqlgen::desc(sqlgen::col<"o", &Order::order_date>))
  | sqlgen::to<std::vector<QueryResult>>();

  // 5. Execute query
  auto result = query(conn);

  if (!result) {
    return {};
  }

  // 6. Transform QueryResult to PurchaseHistory
  std::vector<PurchaseHistory> purchase_history;
  purchase_history.reserve(result->size());

  for (const auto& row : *result) {
    purchase_history.push_back(PurchaseHistory{
      .product_name = row.name,
      .order_date = row.order_date,
      .quantity = row.quantity
    });
  }

  return purchase_history;
}

}  // namespace query_customer_purchase_history
