  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_result) {
    return {};
  }

  // Create table accessors with aliases
  auto o = sqlgen::table<Order, "o">();
  auto c = sqlgen::table<Customer, "c">();

  // Build the query: SELECT o.order_id, c.name, o.total_amount, o.order_date
  // FROM Order o INNER JOIN Customer c ON o.customer_id = c.customer_id
  // WHERE o.total_amount > 1000 ORDER BY o.total_amount DESC
  auto query = sqlgen::select_from<Order, "o">(
      o.order_id,
      c.name, 
      o.total_amount,
      o.order_date
  )
  | sqlgen::inner_join<Customer, "c">(o.customer_id == c.customer_id)
  | sqlgen::where(o.total_amount > 1000.0)
  | sqlgen::order_by(sqlgen::desc(o.total_amount))
  | sqlgen::to<std::vector<OrderView>>();

  // Execute the query
  auto result = query(*conn_result);

  if (result) {
    return *result;
  }

  return {};
}

}  // namespace query_high_value_orders
