#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  if (!conn) {
    return {};
  }

  // SQLite doesn't support RIGHT JOIN natively, so we simulate it using LEFT JOIN
  // To demonstrate RIGHT JOIN for departments (include all departments):
  // We perform: Department LEFT JOIN Project
  // This includes all departments, even those without projects
  std::string query = 
    "SELECT d.name as department_name, p.name as project_name "
    "FROM Department d LEFT JOIN Project p ON d.department_id = p.department_id";

  // Execute the query and retrieve results
  auto result = conn.value()->template read<std::vector<DepProj>>(query);

  if (result) {
    return result.value();
  }

  return {};
}

}  // namespace right_join_departments_projects
```

This implementation:

1. **Connects to the database**: Uses `sqlgen::sqlite::connect()` to connect to "test_db.sqlite"

2. **Simulates RIGHT JOIN**: Since SQLite doesn't support RIGHT JOIN natively, the function uses LEFT JOIN with the Department table on the left side, which achieves the same result - including all departments even if they don't have associated projects

3. **Returns joined results**: Executes the query and returns a vector of `DepProj` structs containing department names and project names (with department_name being optional for projects that may not have an associated department)

The query ensures all departments are included in the results, with project information being optional (NULL) for departments without projects.

