/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;

  // Create a connection to access the to_sql method (for dry run)
  auto conn_result = sqlite::Connection::make("test_db.sqlite");
  if (!conn_result) {
    return "";
  }
  auto conn = conn_result.value();

  // Build a complex query with joins, where clause, order_by, and limit
  // SELECT A.id, A.name, B.score FROM A
  // JOIN B ON A.id = B.a_id
  // WHERE B.score > 10.0 AND A.name LIKE '%x%'
  // ORDER BY B.score DESC
  // LIMIT 10

  auto query = select_from<A, "a">(
      col<&A::id>,
      col<&A::name>
  )
  | join<B, "b">().on(col<"a", &A::id> == col<"b", &B::a_id>)
  | where(col<"b", &B::score> > 10.0 && col<"a", &A::name>.like("%x%"))
  | order_by(desc(col<"b", &B::score>))
  | limit(10);

  // Convert the query to dynamic::Statement for to_sql
  auto dynamic_query = transpilation::ToTableOrQuery<decltype(query)>{}(query);
  auto stmt = dynamic::Statement::template make<dynamic::SelectFrom>(
      *std::get_if<Ref<dynamic::SelectFrom>>(&dynamic_query)
  );

  // Use to_sql to generate SQL string without execution (dry run)
  std::string sql = conn->to_sql(stmt);

  return sql;
}

}  // namespace generate_sql_dry_run
