namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  using namespace sqlgen;

  // Create SQLite database connection
  auto conn = sqlite::Connection("test_db.sqlite");

  // Create Event table if it doesn't exist
  conn.execute(
    "CREATE TABLE IF NOT EXISTS Event ("
    "event_id INTEGER PRIMARY KEY, "
    "event_name TEXT NOT NULL, "
    "start_time TEXT NOT NULL, "
    "end_time TEXT, "
    "created_at TEXT NOT NULL)"
  );

  // Clear existing data and insert new events
  conn.execute("DELETE FROM Event");

  // Insert events into the database
  for (const auto& event : events) {
    std::string end_time_str = event.end_time.has_value() 
      ? "'" + event.end_time->value + "'" 
      : "NULL";

    std::string sql = 
      "INSERT INTO Event (event_id, event_name, start_time, end_time, created_at) VALUES (" +
      std::to_string(event.event_id.value) + ", '" +
      event.event_name + "', '" +
      event.start_time.value + "', " +
      end_time_str + ", '" +
      event.created_at.value + "')";

    conn.execute(sql);
  }

  // Get column references
  auto e = col<Event>();

  // Build SELECT query with temporal operations
  auto query = select(
    e.event_id,
    e.event_name,
    day(e.start_time),
    month(e.start_time),
    year(e.start_time),
    hour(e.start_time),
    minute(e.start_time),
    second(e.start_time),
    weekday(e.start_time),
    unixepoch(e.start_time),
    days_between(e.start_time, e.end_time)
  ).from<Event>()
   .where(e.end_time != nullptr);

  // Execute query and retrieve results
  auto result = conn.read<std::vector<TemporalAnalysis>>(query);

  // Return results (handle potential error with empty vector fallback)
  if (result) {
    return result.value();
  }

  return std::vector<TemporalAnalysis>{};
}

}  // namespace analyze_temporal_data
