        << product.product_id.val << ", '"
        << product.name << "', "
        << product.price << ", "
        << product.quantity << ", "
        << product.discount_rate << ")";

    auto insert_result = conn->execute(oss.str());
    if (!insert_result) {
      return {};
    }
  }

  // Build the mathematical operations query using select_from
  std::string query_sql = R"(
    SELECT 
      product_id,
      name,
      ABS(price) as abs_price,
      CAST(CEIL(price) AS REAL) as ceil_price,
      CAST(FLOOR(price) AS REAL) as floor_price,
      ROUND(price, 2) as rounded_price,
      EXP(discount_rate/100.0) as exp_discount,
      LN(price) as ln_price,
      LOG2(quantity) as log2_quantity,
      SIN(discount_rate) as sin_discount,
      COS(discount_rate) as cos_discount,
      TAN(discount_rate) as tan_discount,
      SQRT(quantity) as sqrt_quantity
    FROM Product
  )";

  // Create a dynamic SelectFrom query
  sqlgen::dynamic::SelectFrom query{query_sql};

  // Read results
  auto result = conn->read<std::vector<MathAnalysis>>(query);

  if (result) {
    return *result;
  }

  return {};
}

