#include <optional>
#include <sstream>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Create database connection
  auto conn_result = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = std::move(conn_result.value());

  // Create OrderItem table if not exists
  const std::string create_table_sql = R"(
    CREATE TABLE IF NOT EXISTS OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )";

  auto create_result = conn->execute(create_table_sql);
  if (!create_result) {
    return {};
  }

  // Clear existing data
  auto delete_result = conn->execute("DELETE FROM OrderItem");
  if (!delete_result) {
    return {};
  }

  // Insert items into the table
  for (const auto& item : items) {
    std::ostringstream insert_sql;
    insert_sql << "INSERT INTO OrderItem (item_id, order_id, product_id, unit_price, quantity, discount_rate, tax_rate) VALUES ("
               << item.item_id.value << ", "
               << item.order_id << ", "
               << item.product_id << ", "
               << item.unit_price << ", "
               << item.quantity << ", ";

    if (item.discount_rate.has_value()) {
      insert_sql << item.discount_rate.value();
    } else {
      insert_sql << "NULL";
    }
    insert_sql << ", ";

    if (item.tax_rate.has_value()) {
      insert_sql << item.tax_rate.value();
    } else {
      insert_sql << "NULL";
    }
    insert_sql << ")";

    auto insert_result = conn->execute(insert_sql.str());
    if (!insert_result) {
      return {};
    }
  }

  // Query with calculations - perform all arithmetic operations
  const std::string query_sql = R"(
    SELECT 
      item_id,
      order_id,
      product_id,
      unit_price,
      quantity,
      COALESCE(discount_rate, 0) as discount_rate,
      COALESCE(tax_rate, 0) as tax_rate,
      (unit_price * quantity) as gross_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100.0)) as discounted_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100.0) * (1 + COALESCE(tax_rate, 0)/100.0)) as final_total,
      (unit_price * quantity / quantity) as unit_cost,
      (quantity % 10) as quantity_group,
      (unit_price * 0.3) as estimated_profit
    FROM OrderItem
  )";

  // Use sqlgen's read functionality to execute query and map to OrderMetrics
  sqlgen::dynamic::SelectFrom query{query_sql};
  auto result = conn->read<std::vector<OrderMetrics>>(query);

  if (result) {
    return std::move(result.value());
  }

  return {};
}

}  // namespace calculate_order_metrics
