/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::Connection::make("test_db.sqlite");

  // Build the query: select from Order table with alias "o"
  // Join with Customer and Payment tables
  // Select order_id, customer name (aliased as customer_name), and amount
  // Order by amount in descending order
  auto query = 
    sqlgen::select_from<Order, "o">(
      sqlgen::col<"o", &Order::order_id>,
      sqlgen::as<"customer_name">(sqlgen::col<"c", &Customer::name>),
      sqlgen::col<"p", &Payment::amount>
    )
    | sqlgen::inner_join<Customer, "c">(
        sqlgen::col<"c", &Customer::customer_id> == sqlgen::col<"o", &Order::customer_id>
      )
    | sqlgen::inner_join<Payment, "p">(
        sqlgen::col<"p", &Payment::order_id> == sqlgen::col<"o", &Order::order_id>
      )
    | sqlgen::order_by(sqlgen::desc(sqlgen::col<"p", &Payment::amount>))
    | sqlgen::to<std::vector<Consolidated>>();

  // Execute the query and return results
  return query(conn).value();
}

}  // namespace join_orders_customers_payments
