 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Update all notes: replace "foo" with "bar" in content
  // Equivalent to: UPDATE Notes SET content = REPLACE(content, 'foo', 'bar')
  auto updated = conn | update<Note>(
    set(&Note::content, replace(&Note::content, "foo", "bar"))
  );

  // Query all updated notes
  auto notes_result = updated 
    | select<Note>()
    | into_vector();

  // Convert Note to UpdatedNote format for verification
  std::vector<UpdatedNote> result;
  if (notes_result) {
    for (const auto& note : notes_result.value()) {
      result.push_back(UpdatedNote{
        .note_id = note.note_id,
        .updated_content = note.content
      });
    }
  }

  return result;
}

}  // namespace replace_text_in_notes
