/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen;

  // Connect to database
  auto conn = sqlite::Connection::make("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Drop and recreate table
  if (!(*conn)->execute("DROP TABLE IF EXISTS Inventory")) {
    return false;
  }

  if (!(*conn)->execute(
    "CREATE TABLE Inventory ("
    "item_id INTEGER PRIMARY KEY, "
    "name TEXT NOT NULL, "
    "quantity INTEGER NOT NULL, "
    "location TEXT)")) {
    return false;
  }

  // Bulk write items
  dynamic::Write write_stmt{
    .table = dynamic::Table{"Inventory"},
    .columns = {"item_id", "name", "quantity", "location"}
  };

  if (!(*conn)->start_write(write_stmt)) {
    return false;
  }

  if (!(*conn)->write(items.begin(), items.end())) {
    return false;
  }

  if (!(*conn)->end_write()) {
    return false;
  }

  // Read items with quantity > 50, ordered by quantity DESC
  auto query = select_from<Inventory>(
    col<&Inventory::item_id>,
    col<&Inventory::name>,
    col<&Inventory::quantity>,
    col<&Inventory::location>
  ) | where(col<&Inventory::quantity> > 50)
    | order_by(desc(col<&Inventory::quantity>))
    | to<std::vector<Inventory>>;

