#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  auto conn = sqlgen::sqlite::Connection::open("test_db.sqlite");

  // SQLite doesn't support FULL JOIN natively, so we simulate it using UNION
  // This combines:
  // 1. LEFT JOIN: all suppliers with their products (or NULL if no products)
  // 2. Products without suppliers (right side of FULL JOIN)
  const std::string query = R"(
    SELECT s.name AS supplier_name, p.name AS product_name
    FROM Supplier s
    LEFT JOIN Product p ON s.supplier_id = p.supplier_id
    UNION
    SELECT COALESCE(s.name, '') AS supplier_name, p.name AS product_name
    FROM Product p
    LEFT JOIN Supplier s ON s.supplier_id = p.supplier_id
    WHERE s.supplier_id IS NULL
  )";

  auto result = conn.and_then([&query](auto c) {
    return c->template read<std::vector<SupProd>>(query);
  });

  return result.value_or(std::vector<SupProd>{});
}

}  // namespace full_join_suppliers_products

