namespace select_from_read_to_vector {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  int pages;
};

/**
 * description: select_from_read_to_vector.
 * This function demonstrates how to read data from a table using sqlgen read API and store it in a vector.
 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  // Create an in-memory SQLite connection
  auto conn_result = sqlgen::sqlite::Connection::make(":memory:");
  if (!conn_result) {
    return {};
  }
  auto conn = *conn_result;

  // Create the books table
  conn->execute("CREATE TABLE Book (book_id INTEGER PRIMARY KEY, title TEXT NOT NULL, pages INTEGER NOT NULL)");

  // Insert some sample data
  conn->execute("INSERT INTO Book (book_id, title, pages) VALUES (1, 'Book A', 100)");
  conn->execute("INSERT INTO Book (book_id, title, pages) VALUES (2, 'Book B', 300)");
  conn->execute("INSERT INTO Book (book_id, title, pages) VALUES (3, 'Book C', 200)");

  // Use select_from with to<std::vector<Book>>
  // Select all fields and order by pages in descending order
  auto query = sqlgen::select_from<Book>(
    sqlgen::col<"book_id">, 
    sqlgen::col<"title">, 
    sqlgen::col<"pages">
  ) | sqlgen::order_by(sqlgen::col<"pages">.desc())
    | sqlgen::to<std::vector<Book>>;

  // Execute the query
  auto result = query(conn);

  // Return the vector of books (or empty vector on error)
  return result.value_or(std::vector<Book>{});
}

}  // namespace select_from_read_to_vector
