  // Create a SELECT query for User table where age > 18 with limit 10
  auto query = transpilation::read_to_select_from<User>(
    where(c(&User::age) > 18),
    limit(10)
  );

  // Convert the query to SQL string using SQLite dialect
  return sqlite::to_sql(query);
